/**
     *
     * This is used by {@link org.elasticsearch.xpack.esql.stats.PlanningMetrics} to collect query statistics
     * It can return
     * <ul>
     *     <li>"FROM" if this a <code>|FROM idx</code> command</li>
     *     <li>"FROM TS" if it is the result of a <code>| METRICS idx some_aggs() BY fields</code> command</li>
     *     <li>"METRICS" if it is the result of a <code>| METRICS idx</code> (no aggs, no groupings)</li>
     * </ul>
     */
    @Override
    public String metricName() {
        return commandName;
    }

@Override
    public String metricName() {
        return switch (aggregateType) {
            case STANDARD -> "STATS";
            case METRICS -> "METRICS";
        };
    }

/**
 * Interface for plan nodes that need to be accounted in the statistics
 */
public interface MetricsAware {

    /**
     * @return the name of the metric. Only needs to be overwriten if the metric name doesn't match the class name.
     */
    default String metricName() {
        return getClass().getSimpleName().toUpperCase(Locale.ROOT);
    }
}

public LogicalPlanBuilder(QueryParams params, PlanningMetrics metrics) {
        super(params, metrics);
        this.metrics = metrics;
